import{z as F,x as A,o as t,c as S,q as l,j as E,D as e,d as r,s as i,S as o,b as s}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"FCFS 与 SJF","description":"","frontmatter":{"title":"FCFS 与 SJF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fcfs-sjf.md","filePath":"cs/fcfs-sjf.md","lastUpdated":1791413859000}'),p={name:"cs/fcfs-sjf.md"};function d(B,a,C,f,m,c){const n=A("Mermaid");return t(),S("div",null,[a[2]||(a[2]=l('<h1 id="fcfs-与-sjf" tabindex="-1">FCFS 与 SJF <a class="header-anchor" href="#fcfs-与-sjf" aria-label="Permalink to &quot;FCFS 与 SJF&quot;">​</a></h1><div class="epigraph"><p>先来先服务实现最直；短作业优先降低平均等待，但要知道或估计下一次 CPU 突发有多长。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/runqueue">上一课</a>给出可运行容器。<a href="/cs/scheduling-metrics">调度指标</a>已警告：换尺子，名次就换。缺口是两条经典<strong>非抢占</strong>（SJF 可做成抢占的 SRTF）策略：FCFS 按入队序；SJF 按下一次突发最短者先跑。本课对着同一组到达与突发比较，不引入时间片。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FCFS：runqueue 当 FIFO，实现即入队出队。长 CPU 型先到，后面一串 I/O 型的等待被拖长，即传送带效应。SJF：选估计突发最短的，平均等待往往更优；证明「非抢占 SJF 平均等待最优」教材可引，本课只锁定直觉与代价——<strong>长度未知</strong>。缺口不是新的队列结构，而是用指标解释这两种取队头的规则。</p><p><span class="marginnote">直觉类比：传送带效应就像超市只有一个收银台——排你前面的人推着满满一车，你只买一瓶水，也得等他把整车结完。FCFS 不看购物多少只看排队先后，于是短任务的平均体验被长任务拖垮。</span></p><p><span class="marginnote">抢占式最短剩余时间（SRTF）在新短作业到达时打断当前长作业，响应更好，切换更多。估计常用指数平均：最近突发与历史的凸组合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定到达时间与突发，画出甘特图，算平均等待与周转。FCFS 不需要估计。SJF 需要预言或估计；估计偏长则退化成近 FCFS，偏短则可能饿死长作业——饥饿是公平尺子，不是平均等待。本课点名饥饿，不把多级反馈请进来。</p>',9)),(t(),E(o,null,{default:e(()=>[i(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20FCFS%5B%22FCFS%3A%20%E5%85%A5%E9%98%9F%E5%BA%8F%22%5D%0A%20%20ARR%20--%3E%20SJF%5B%22SJF%3A%20%E6%9C%80%E7%9F%AD%E7%AA%81%E5%8F%91%E5%85%88%22%5D%0A%20%20FCFS%20--%3E%20M%5B%22%E7%AD%89%E5%BE%85%E4%B8%8E%E5%91%A8%E8%BD%AC%22%5D%0A%20%20SJF%20--%3E%20M%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("p",null,"两者默认跑到突发结束（阻塞或结束）才再选，除非用 SRTF。",-1)),a[4]||(a[4]=s("h2",{id:"机制",tabindex:"-1"},[r("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=s("p",null,"FCFS 对 I/O 型不友好当它排在长计算后面；SJF 照顾 I/O 型（短突发）从而抬利用率。交互响应仍可能差：一个中等突发也能挡住击键，因为没有时间片上限。这把下一课轮转的动机钉在「即使长度未知，也要定期让出」。",-1)),(t(),E(o,null,{default:e(()=>[i(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E4%B8%89%E4%B8%AA%E4%BD%9C%E4%B8%9A%E5%90%8C%E6%97%B6%E5%88%B0%E8%BE%BE%3A%20A%20%E8%A6%81%2024%2C%20B%20%E8%A6%81%203%2C%20C%20%E8%A6%81%203%22%5D%20--%3E%20F%5B%22FCFS%20%E6%8C%89%E5%85%88%E5%90%8E%3A%20%E5%85%88%E8%B7%91%20A%22%5D%0A%20%20F%20--%3E%20F1%5B%22%E9%A1%BA%E5%BA%8F%20A%2C%20B%2C%20C%22%5D%0A%20%20F1%20--%3E%20FW%5B%22B%20%E7%AD%89%2024%2C%20C%20%E7%AD%89%2027%2C%20%E5%B9%B3%E5%9D%87%E7%AD%89%E5%BE%85%2017%22%5D%0A%20%20J%20--%3E%20S%5B%22SJF%20%E6%8C%89%E9%95%BF%E7%9F%AD%3A%20%E5%85%88%E8%B7%91%20B%20%E5%92%8C%20C%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E9%A1%BA%E5%BA%8F%20B%2C%20C%2C%20A%22%5D%0A%20%20S1%20--%3E%20SW%5B%22B%20%E7%AD%89%200%2C%20C%20%E7%AD%89%203%2C%20A%20%E7%AD%89%206%2C%20%E5%B9%B3%E5%9D%87%E7%AD%89%E5%BE%85%203%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：初学者容易以为 SJF 只是「让长作业多等一会儿」。实际上若短作业源源不断到达，长作业可能一次都轮不上——这叫饥饿。平均等待这把尺子根本不度量公平，所以「平均等待最优」与「有人永远等不到」可以同时成立。</span></p><p><span class="marginnote">术语翻译：指数平均就是把「上一次实际跑了多久」和「之前的估计」按比例掺在一起：\\(\\tau_{n+1} = \\alpha t_n + (1-\\alpha)\\tau_n\\)。取 \\(\\alpha = 0.5\\) 意味着最新一次突发占一半话语权——既不像只看上次那样大惊小怪，也不会对行为变化反应迟钝。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把实时截止当成短作业。也不把 SJF 说成 Linux 默认。估计误差与恶意谎报长度（用户说自己很短）在开放系统里存在；内核若用实测突发，谎报无效。</p><p>后课默认：非抢占策略平均等待可以很好，响应仍可很差。定期抢占的时间片轮转，下一课收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FCFS 简单，有传送带效应；SJF 降平均等待，依赖估计，可饿死长作业。</li><li>两者都不自动给出交互响应上限。</li><li>时间片轮转是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',7))])}const D=F(p,[["render",d]]);export{h as __pageData,D as default};
